function(container, apiUrl, tables) {
  const tbody = container.querySelector("#error-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const detailContent = container.querySelector("#detail-content");
  const filterCustomer = container.querySelector("#filter-customer");
  const filterSalesPerson = container.querySelector("#filter-sales-person");
  const filterErrorType = container.querySelector("#filter-error-type");
  const filterSeverity = container.querySelector("#filter-severity");
  const filterStatus = container.querySelector("#filter-status");
  const filterDateFrom = container.querySelector("#filter-date-from");
  const btnSearch = container.querySelector("#btn-search");
  const btnReset = container.querySelector("#btn-reset");
  const btnExport = container.querySelector("#btn-export");
  const btnBulkUpdate = container.querySelector("#btn-bulk-update");
  const btnDataInput = container.querySelector("#btn-data-input");
  const kpiPending = container.querySelector("#kpi-pending");
  const kpiInProgress = container.querySelector("#kpi-in-progress");
  const kpiCompleted = container.querySelector("#kpi-completed");
  const kpiBillingImpact = container.querySelector("#kpi-billing-impact");
  const totalCount = container.querySelector("#total-count");

  let allRows = [];
  let selectedRowId = null;

  // 重要度バッジ色
  function getSeverityColor(severity) {
    if (severity === "高") return "#f44336";
    if (severity === "中") return "#ffc107";
    return "#4caf50";
  }

  // ステータスバッジ色
  function getStatusColor(status) {
    if (status === "未対応") return "#ff6a00";
    if (status === "対応中") return "#ffc107";
    return "#4caf50";
  }

  // 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.04); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background=''">
        <td style="padding: 8px; color: var(--text);">${r.検出日時 ? new Date(r.検出日時).toLocaleDateString('ja-JP', {month:'2-digit', day:'2-digit'}) : "-"}</td>
        <td style="padding: 8px; color: var(--text);">${r.顧客名 || "-"}</td>
        <td style="padding: 8px; color: var(--text);">${r.営業担当者 || "-"}</td>
        <td style="padding: 8px; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${r.不足項目名 || "-"}</td>
        <td style="padding: 8px; color: var(--text);">${r.異常タイプ || "-"}</td>
        <td style="padding: 8px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${getSeverityColor(r.重要度)}; color: #fff; font-size: 11px; font-weight: 600;">${r.重要度 || "-"}</span>
        </td>
        <td style="padding: 8px; text-align: center;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${getStatusColor(r.対応状況)}; color: #fff; font-size: 11px; font-weight: 600;">${r.対応状況 || "-"}</span>
        </td>
        <td style="padding: 8px; text-align: center; color: ${r.請求処理への影響 ? '#f44336' : 'var(--text-muted)'};">${r.請求処理への影響 ? "◆" : "○"}</td>
      </tr>
    `).join("");
    totalCount.textContent = rows.length;
    updateKPIs(rows);
  }

  // KPI 更新
  function updateKPIs(rows) {
    const pending = rows.filter(r => r.対応状況 === "未対応").length;
    const inProgress = rows.filter(r => r.対応状況 === "対応中").length;
    const completed = rows.filter(r => r.対応状況 === "完了").length;
    const billingImpact = rows.filter(r => r.請求処理への影響).length;
    kpiPending.textContent = pending;
    kpiInProgress.textContent = inProgress;
    kpiCompleted.textContent = completed;
    kpiBillingImpact.textContent = billingImpact;
  }

  // 詳細表示
  function showDetail(row) {
    selectedRowId = row.id;
    const html = `
      <div style="padding: 12px; font-size: 12px;">
        <div style="margin-bottom: 12px;">
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">営業データID</div>
          <div style="color: var(--text); font-weight: 500; word-break: break-all;">${row.営業データID || "-"}</div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">顧客名</div>
          <div style="color: var(--text); font-weight: 500;">${row.顧客名 || "-"}</div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">営業担当者</div>
          <div style="color: var(--text); font-weight: 500;">${row.営業担当者 || "-"}</div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">不足項目</div>
          <div style="color: var(--text); font-weight: 500;">${row.不足項目名 || "-"}</div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">エラー種別</div>
          <div style="color: var(--text); font-weight: 500;">${row.異常タイプ || "-"}</div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">検出値</div>
          <div style="color: var(--text); font-weight: 500; word-break: break-all;">${row.検出値 || "-"}</div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">期待値</div>
          <div style="color: var(--text); font-weight: 500; word-break: break-all;">${row.期待値 || "-"}</div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">検証ルール</div>
          <div style="color: var(--text); font-weight: 500;">${row.検証ルール名 || "-"}</div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">検出日時</div>
          <div style="color: var(--text); font-weight: 500;">${row.検出日時 ? new Date(row.検出日時).toLocaleString('ja-JP') : "-"}</div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">ステータス</div>
          <select data-testid="detail-status-select" style="padding: 4px 6px; border: 1px solid rgba(255,255,255,0.18); border-radius: 3px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px; width: 100%;">
            <option value="未対応" ${row.対応状況 === "未対応" ? "selected" : ""}>未対応</option>
            <option value="対応中" ${row.対応状況 === "対応中" ? "selected" : ""}>対応中</option>
            <option value="完了" ${row.対応状況 === "完了" ? "selected" : ""}>完了</option>
          </select>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">対応コメント</div>
          <textarea data-testid="detail-comment-textarea" style="padding: 6px; border: 1px solid rgba(255,255,255,0.18); border-radius: 3px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px; width: 100%; min-height: 60px; resize: vertical;">${row.対応コメント || ""}</textarea>
        </div>
        <button id="btn-save-detail" data-testid="save-detail-button" class="action-btn" style="width: 100%; padding: 6px; font-size: 12px;">保存</button>
      </div>
    `;
    detailContent.innerHTML = html;

    const btnSaveDetail = detailContent.querySelector("#btn-save-detail");
    btnSaveDetail.addEventListener("click", async () => {
      const newStatus = detailContent.querySelector('[data-testid="detail-status-select"]').value;
      const newComment = detailContent.querySelector('[data-testid="detail-comment-textarea"]').value;
      const updated = await window.aivicApi.update(0, row.id, {
        対応状況: newStatus,
        対応コメント: newComment,
        対応日時: new Date().toISOString()
      });
      if (updated) {
        window.aivicApi.list(0).then(rows => {
          allRows = rows;
          applyFilters();
        });
      }
    });
  }

  // フィルター適用
  function applyFilters() {
    let filtered = allRows;
    const customer = filterCustomer.value.toLowerCase();
    const salesperson = filterSalesPerson.value.toLowerCase();
    const errorType = filterErrorType.value;
    const severity = filterSeverity.value;
    const status = filterStatus.value;
    const dateFrom = filterDateFrom.value;

    filtered = filtered.filter(r => {
      if (customer && !(r.顧客名 || "").toLowerCase().includes(customer)) return false;
      if (salesperson && !(r.営業担当者 || "").toLowerCase().includes(salesperson)) return false;
      if (errorType && r.異常タイプ !== errorType) return false;
      if (severity && r.重要度 !== severity) return false;
      if (status && r.対応状況 !== status) return false;
      if (dateFrom && r.検出日時) {
        const rowDate = new Date(r.検出日時).toISOString().split('T')[0];
        if (rowDate < dateFrom) return false;
      }
      return true;
    });

    renderRows(filtered);
  }

  // 初期データ描画
  window.aivicApi.list(0).then(rows => {
    allRows = rows;
    renderRows(rows);
  });

  // イベントリスナー
  btnSearch.addEventListener("click", applyFilters);
  btnReset.addEventListener("click", () => {
    filterCustomer.value = "";
    filterSalesPerson.value = "";
    filterErrorType.value = "";
    filterSeverity.value = "";
    filterStatus.value = "";
    filterDateFrom.value = "";
    window.aivicApi.list(0).then(rows => {
      allRows = rows;
      renderRows(rows);
    });
  });

  // 行クリックで詳細表示
  tbody.addEventListener("click", e => {
    const tr = e.target.closest("tr");
    if (tr) {
      const id = tr.dataset.id;
      const row = allRows.find(r => r.id === id);
      if (row) showDetail(row);
    }
  });

  // CSV エクスポート
  btnExport.addEventListener("click", () => {
    const headers = ["検出日時", "顧客名", "営業担当者", "不足項目", "エラー種別", "重要度", "ステータス", "請求影響", "対応コメント"];
    const rows = allRows.map(r => [
      r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP') : "",
      r.顧客名 || "",
      r.営業担当者 || "",
      r.不足項目名 || "",
      r.異常タイプ || "",
      r.重要度 || "",
      r.対応状況 || "",
      r.請求処理への影響 ? "はい" : "いいえ",
      r.対応コメント || ""
    ]);
    const csv = "\uFEFF" + [headers, ...rows].map(r => r.map(c => `"${String(c).replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "error-notification-" + new Date().toISOString().split('T')[0] + ".csv";
    link.click();
  });

  // 一括対応
  btnBulkUpdate.addEventListener("click", () => {
    const pending = allRows.filter(r => r.対応状況 === "未対応");
    if (pending.length === 0) {
      alert("未対応の項目がありません");
      return;
    }
    if (confirm(`未対応の ${pending.length} 件を対応中に変更しますか？`)) {
      Promise.all(pending.map(r => window.aivicApi.update(0, r.id, { 対応状況: "対応中" }))).then(() => {
        window.aivicApi.list(0).then(rows => {
          allRows = rows;
          applyFilters();
        });
      });
    }
  });

  // データ入力画面へ
  btnDataInput.addEventListener("click", () => {
    window.showScreen("scr-1781953462575");
  });
}

function(container, apiUrl, tables) {
  // ============================================
  // 1. 再描画関数の定義
  // ============================================

  function renderCustomerSummary(rows) {
    const tbody = container.querySelector("#customer-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: rgba(0,0,0,0.1);"><td style="padding: 8px; color: var(--text-muted);" colspan="3">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 8px; color: var(--text);">${r.顧客ID || r.customer_id || ''}</td>
        <td style="padding: 8px; text-align: right; color: var(--text); font-weight: 500;">¥${(r.請求金額 || r.billing_amount || 0).toLocaleString()}</td>
        <td style="padding: 8px; text-align: right; color: var(--text-muted);">${r.件数 || r.count || 0}</td>
      </tr>
    `).join("");
  }

  function renderServiceSummary(rows) {
    const tbody = container.querySelector("#service-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: rgba(0,0,0,0.1);"><td style="padding: 8px; color: var(--text-muted);" colspan="3">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 8px; color: var(--text);">${r.サービスID || r.service_id || ''}</td>
        <td style="padding: 8px; text-align: right; color: var(--text); font-weight: 500;">¥${(r.請求金額 || r.billing_amount || 0).toLocaleString()}</td>
        <td style="padding: 8px; text-align: right; color: var(--text-muted);">${r.件数 || r.count || 0}</td>
      </tr>
    `).join("");
  }

  function renderMissingData(rows) {
    const tbody = container.querySelector("#missing-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: rgba(0,0,0,0.1);"><td style="padding: 6px; color: var(--text-muted);" colspan="2">不足データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 6px; color: var(--text);">${r.不足項目名 || r.missing_field || ''}</td>
        <td style="padding: 6px; text-align: center; color: var(--text-muted);">${r.件数 || r.count || 0}</td>
      </tr>
    `).join("");
  }

  // ============================================
  // 2. 初期データ表示
  // ============================================

  // tables[0] = 営業データ、tables[1] = 検証ルール、tables[2] = 異常検出ログ、
  // tables[3] = 請求対象項目定義、tables[4] = 顧客請求集計、tables[5] = サービス請求集計、
  // tables[6] = メタデータ、tables[7] = 月次サマリー、tables[8] = 検証結果、tables[9] = 不足データ通知

  renderCustomerSummary([]);
  renderServiceSummary([]);
  renderMissingData([]);

  // ============================================
  // 3. 計算実行ボタン
  // ============================================

  container.querySelector("#btn-calculate").addEventListener("click", async () => {
    const periodFrom = container.querySelector("#period-from").value;
    const periodTo = container.querySelector("#period-to").value;
    const customerFilter = container.querySelector("#customer-filter").value;
    const serviceFilter = container.querySelector("#service-filter").value;
    const ruleMandatory = container.querySelector("#rule-mandatory").checked;
    const ruleRange = container.querySelector("#rule-range").checked;
    const ruleDuplicate = container.querySelector("#rule-duplicate").checked;

    // ステータス更新
    container.querySelector("#calc-status").textContent = "計算中...";
    container.querySelector("#calc-status").style.color = "#ffd700";

    try {
      // 営業データを取得
      const salesData = await window.aivicApi.list(0);
      if (!salesData) {
        container.querySelector("#calc-status").textContent = "エラー: データ取得失敗";
        container.querySelector("#calc-status").style.color = "#ff6b6b";
        return;
      }

      // フィルタリング
      let filtered = salesData.filter(r => {
        const txDate = r.取引日 || r.transaction_date || '';
        const custId = r.顧客ID || r.customer_id || '';
        const svcId = r.商品ID || r.product_id || '';
        const billFlag = r.請求対象フラグ || r.billing_target_flag;

        // 期間フィルタ
        if (periodFrom && txDate < periodFrom) return false;
        if (periodTo && txDate > periodTo) return false;

        // 顧客フィルタ
        if (customerFilter && custId !== customerFilter) return false;

        // サービスフィルタ
        if (serviceFilter && svcId !== serviceFilter) return false;

        // 請求対象フラグ
        if (!billFlag) return false;

        return true;
      });

      // 顧客別集計
      const customerSummary = {};
      filtered.forEach(r => {
        const custId = r.顧客ID || r.customer_id || 'Unknown';
        if (!customerSummary[custId]) {
          customerSummary[custId] = { 顧客ID: custId, 請求金額: 0, 件数: 0 };
        }
        customerSummary[custId].請求金額 += r.取引金額 || r.transaction_amount || 0;
        customerSummary[custId].件数 += 1;
      });

      // サービス別集計
      const serviceSummary = {};
      filtered.forEach(r => {
        const svcId = r.商品ID || r.product_id || 'Unknown';
        if (!serviceSummary[svcId]) {
          serviceSummary[svcId] = { サービスID: svcId, 請求金額: 0, 件数: 0 };
        }
        serviceSummary[svcId].請求金額 += r.取引金額 || r.transaction_amount || 0;
        serviceSummary[svcId].件数 += 1;
      });

      // 検証結果集計
      const validationData = await window.aivicApi.list(8);
      let passCount = 0, failCount = 0;
      if (validationData) {
        validationData.forEach(v => {
          const status = v.検証ステータス || v.validation_status || '';
          if (status === '合格') passCount++;
          else if (status === '不合格') failCount++;
        });
      }

      // 不足データ取得
      const missingData = await window.aivicApi.list(9);
      const missingGrouped = {};
      if (missingData) {
        missingData.forEach(m => {
          const field = m.不足項目名 || m.missing_field || 'Unknown';
          if (!missingGrouped[field]) {
            missingGrouped[field] = { 不足項目名: field, 件数: 0 };
          }
          missingGrouped[field].件数 += 1;
        });
      }

      // 描画
      renderCustomerSummary(Object.values(customerSummary));
      renderServiceSummary(Object.values(serviceSummary));
      renderMissingData(Object.values(missingGrouped));

      // 品質スコア表示
      container.querySelector("#quality-pass").textContent = `${passCount}件`;
      container.querySelector("#quality-fail").textContent = `${failCount}件`;

      // ステータス完了
      container.querySelector("#calc-status").textContent = "計算完了 ✓";
      container.querySelector("#calc-status").style.color = "#4ade80";

    } catch (err) {
      console.error("計算エラー:", err);
      container.querySelector("#calc-status").textContent = "エラー: 計算失敗";
      container.querySelector("#calc-status").style.color = "#ff6b6b";
    }
  });

  // ============================================
  // 4. CSVエクスポートボタン
  // ============================================

  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const customerRows = Array.from(container.querySelector("#customer-tbody").querySelectorAll("tr"))
        .filter(tr => tr.textContent.includes("¥"))
        .map(tr => {
          const cells = tr.querySelectorAll("td");
          return {
            顧客ID: cells[0]?.textContent || '',
            請求金額: cells[1]?.textContent.replace(/[¥,]/g, '') || '0',
            件数: cells[2]?.textContent || '0'
          };
        });

      const serviceRows = Array.from(container.querySelector("#service-tbody").querySelectorAll("tr"))
        .filter(tr => tr.textContent.includes("¥"))
        .map(tr => {
          const cells = tr.querySelectorAll("td");
          return {
            サービスID: cells[0]?.textContent || '',
            請求金額: cells[1]?.textContent.replace(/[¥,]/g, '') || '0',
            件数: cells[2]?.textContent || '0'
          };
        });

      // CSV生成（顧客別）
      const customerCsv = [
        '\uFEFF顧客ID,請求金額,件数',
        ...customerRows.map(r => `${r.顧客ID},"${r.請求金額}",${r.件数}`)
      ].join('\n');

      // CSV生成（サービス別）
      const serviceCsv = [
        '\uFEFFサービスID,請求金額,件数',
        ...serviceRows.map(r => `${r.サービスID},"${r.請求金額}",${r.件数}`)
      ].join('\n');

      // 両方を結合
      const fullCsv = customerCsv + '\n\n' + serviceCsv;

      // ダウンロード
      const blob = new Blob([fullCsv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `billing_calculation_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

    } catch (err) {
      console.error("エクスポートエラー:", err);
      alert("CSVエクスポートに失敗しました");
    }
  });

  // ============================================
  // 5. 画面遷移リンク（ナビゲーション）
  // ============================================

  // 必要に応じて他画面へのナビゲーションを追加
  // 例: container.querySelector("#link-to-validation").addEventListener("click", () => {
  //   window.showScreen("scr-1781953477562");
  // });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#record-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const validationPanel = container.querySelector("#validation-panel");
  const anomalyPanel = container.querySelector("#anomaly-panel");
  const detailContent = container.querySelector("#detail-content");
  const validationContent = container.querySelector("#validation-content");
  const anomalyContent = container.querySelector("#anomaly-content");
  const editBtn = container.querySelector("#edit-btn");

  let allRows = [];
  let selectedRowId = null;

  // 1. テーブル再描画関数
  function renderRows(rows) {
    allRows = rows;
    tbody.innerHTML = rows.length === 0 
      ? '<tr style="background: rgba(0,0,0,0.15); border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="7" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">検索結果がありません</td></tr>'
