                <span style="background: ${qualityColor}; color: #fff; padding: 2px 6px; border-radius: 3px; display: inline-block; font-weight: 600;">
                  ${qualityStatus}
                </span>
              </td>
              <td style="padding: 8px; text-align: center; color: ${hasAnomaly ? '#ef4444' : '#4ade80'}; font-weight: 600; font-size: 11px;">
                ${hasAnomaly ? '⚠ あり' : '✓ なし'}
              </td>
