                <button class="action-btn secondary" style="padding: 4px 8px; font-size: 10px; white-space: nowrap;">詳細</button>
              </td>
            </tr>
          `;
        }).join("");
  }

  // 2. 初期データ表示
  renderRows(tables[0]?.records || []);

  // 3. 行クリック時に詳細パネルを表示
  container.addEventListener("click", async (e) => {
    const row = e.target.closest("tr[data-id]");
    if (!row) return;

    selectedRowId = row.dataset.id;
    const record = allRows.find(r => (r.営業データID || r.id) === selectedRowId);
    if (!record) return;

    // 基本情報を表示
    detailPanel.style.display = "block";
    detailContent.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>営業データID:</strong> ${record.営業データID || record.id || '-'}</div>
      <div style="margin-bottom: 8px;"><strong>顧客ID:</strong> ${record.顧客ID || '-'}</div>
      <div style="margin-bottom: 8px;"><strong>取引日:</strong> ${record.取引日 ? new Date(record.取引日).toLocaleDateString('ja-JP') : '-'}</div>
      <div style="margin-bottom: 8px;"><strong>取引金額:</strong> ¥${(record.取引金額 || 0).toLocaleString()}</div>
      <div style="margin-bottom: 8px;"><strong>取引種別:</strong> ${record.取引種別 || '-'}</div>
      <div style="margin-bottom: 8px;"><strong>商品ID:</strong> ${record.商品ID || '-'}</div>
      <div style="margin-bottom: 8px;"><strong>数量:</strong> ${record.数量 || '-'}</div>
      <div style="margin-bottom: 8px;"><strong>単価:</strong> ¥${(record.単価 || 0).toLocaleString()}</div>
      <div style="margin-bottom: 8px;"><strong>請求対象:</strong> ${record.請求対象フラグ ? 'はい' : 'いいえ'}</div>
      <div style="margin-bottom: 8px;"><strong>請求済み:</strong> ${record.請求済みフラグ ? 'はい' : 'いいえ'}</div>
      <div style="margin-bottom: 8px;"><strong>品質ステータス:</strong> ${record.データ品質ステータス || '-'}</div>
      ${record.品質エラー内容 ? `<div style="margin-bottom: 8px; color: #ef4444;"><strong>エラー内容:</strong> ${record.品質エラー内容}</div>` : ''}
    `;

