    const validationTable = tables[1];
    if (validationTable) {
      const validationRecords = (validationTable.records || []).filter(v => v.営業データID === selectedRowId);
      if (validationRecords.length > 0) {
        validationPanel.style.display = "block";
        validationContent.innerHTML = validationRecords.map(v => `
          <div style="margin-bottom: 10px; padding: 8px; background: rgba(0,0,0,0.2); border-radius: 3px; border-left: 3px solid ${v.検証ステータス === '合格' ? '#4ade80' : '#ef4444'};">
            <div style="font-weight: 600; margin-bottom: 4px;">${v.検証ルールID || 'ルール'}</div>
            <div style="margin-bottom: 2px;"><strong>ステータス:</strong> ${v.検証ステータス || '-'}</div>
            <div style="margin-bottom: 2px;"><strong>フィールド:</strong> ${v.検証対象フィールド || '-'}</div>
            ${v.エラー内容 ? `<div style="margin-bottom: 2px; color: #fca5a5;"><strong>エラー:</strong> ${v.エラー内容}</div>` : ''}
            <div style="margin-bottom: 2px;"><strong>是正状況:</strong> ${v.是正状況 || '-'}</div>
          </div>
        `).join("");
      } else {
        validationPanel.style.display = "none";
      }
    }

    // 異常検出ログを表示（テーブル3から検索）
    const anomalyTable = tables[2];
    if (anomalyTable) {
      const anomalyRecords = (anomalyTable.records || []).filter(a => a.営業データID === selectedRowId);
      if (anomalyRecords.length > 0) {
        anomalyPanel.style.display = "block";
        anomalyContent.innerHTML = anomalyRecords.map(a => {
          const severityColor = a.重要度 === '高' ? '#ef4444' : a.重要度 === '中' ? '#facc15' : '#4ade80';
          return `
            <div style="margin-bottom: 10px; padding: 8px; background: rgba(0,0,0,0.2); border-radius: 3px; border-left: 3px solid ${severityColor};">
              <div style="font-weight: 600; margin-bottom: 4px;">異常タイプ: ${a.異常タイプ || '-'}</div>
              <div style="margin-bottom: 2px;"><strong>フィールド:</strong> ${a.異常フィールド名 || '-'}</div>
              <div style="margin-bottom: 2px;"><strong>検出値:</strong> ${a.検出値 || '-'}</div>
              <div style="margin-bottom: 2px;"><strong>期待値:</strong> ${a.期待値 || '-'}</div>
              <div style="margin-bottom: 2px;"><strong>重要度:</strong> <span style="color: ${severityColor}; font-weight: 600;">${a.重要度 || '-'}</span></div>
              <div style="margin-bottom: 2px;"><strong>対応状況:</strong> ${a.対応状況 || '-'}</div>
              ${a.対応コメント ? `<div style="margin-bottom: 2px; color: #d0e4ff;"><strong>コメント:</strong> ${a.対応コメント}</div>` : ''}
            </div>
          `;
        }).join("");
      } else {
        anomalyPanel.style.display = "none";
      }
    }

    editBtn.style.display = "block";
  });

  // 4. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const customerId = container.querySelector("[data-testid='customer-id-input']").value.trim();
    const serviceType = container.querySelector("[data-testid='service-type-select']").value;
    const startDate = container.querySelector("[data-testid='billing-start-date']").value;
    const endDate = container.querySelector("[data-testid='billing-end-date']").value;
    const qualityStatus = container.querySelector("[data-testid='quality-status-select']").value;
    const anomalyFlag = container.querySelector("[data-testid='anomaly-flag-select']").value;

    let filtered = allRows;

    if (customerId) {
      filtered = filtered.filter(r => (r.顧客ID || '').includes(customerId));
    }
    if (serviceType) {
      filtered = filtered.filter(r => r.取引種別 === serviceType);
    }
    if (startDate) {
      const start = new Date(startDate);
      filtered = filtered.filter(r => r.取引日 && new Date(r.取引日) >= start);
    }
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59, 999);
      filtered = filtered.filter(r => r.取引日 && new Date(r.取引日) <= end);
    }
    if (qualityStatus) {
      filtered = filtered.filter(r => r.データ品質ステータス === qualityStatus);
    }
    if (anomalyFlag !== "") {
      const flag = anomalyFlag === "true";
      filtered = filtered.filter(r => r.異常フラグ === flag);
    }

    renderRows(filtered);
    detailPanel.style.display = "none";
    validationPanel.style.display = "none";
    anomalyPanel.style.display = "none";
    editBtn.style.display = "none";
  });

  // 5. リセットボタン
  container.querySelector("[data-testid='reset-button']").addEventListener("click", () => {
    container.querySelector("[data-testid='customer-id-input']").value = "";
    container.querySelector("[data-testid='service-type-select']").value = "";
    container.querySelector("[data-testid='billing-start-date']").value = "";
    container.querySelector("[data-testid='billing-end-date']").value = "";
    container.querySelector("[data-testid='quality-status-select']").value = "";
    container.querySelector("[data-testid='anomaly-flag-select']").value = "";
    renderRows(allRows);
    detailPanel.style.display = "none";
    validationPanel.style.display = "none";
    anomalyPanel.style.display = "none";
    editBtn.style.display = "none";
  });

  // 6. CSV出力ボタン
  container.querySelector("[data-testid='export-button']").addEventListener("click", () => {
    if (allRows.length === 0) {
      alert("出力するデータがありません");
      return;
    }

    const headers = ["営業データID", "顧客ID", "取引日", "取引金額", "取引種別", "商品ID", "数量", "単価", "請求対象", "請求済み", "品質ステータス", "エラー内容"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...allRows.map(r => [
        r.営業データID || r.id || "",
        r.顧客ID || "",
        r.取引日 ? new Date(r.取引日).toLocaleDateString('ja-JP') : "",
        r.取引金額 || "",
        r.取引種別 || "",
        r.商品ID || "",
        r.数量 || "",
        r.単価 || "",
        r.請求対象フラグ ? "はい" : "いいえ",
        r.請求済みフラグ ? "はい" : "いいえ",
        r.データ品質ステータス || "",
        r.品質エラー内容 ? `"${r.品質エラー内容.replace(/"/g, '""')}"` : ""
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `営業データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 7. データ編集ボタン
  editBtn.addEventListener("click", () => {
    if (selectedRowId) {
      window.showScreen("scr-1781953462575");
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const billingTableIndex = 0; // 顧客請求集計
  const serviceTableIndex = 1; // サービス請求集計
  const qualityTableIndex = 2; // データ品質検証結果
  const anomalyTableIndex = 3; // 営業データ異常検出ログ
  const missingTableIndex = 4; // 不足データ通知ログ

  let currentBillingData = [];
  let currentServiceData = [];
  let appliedDiscount = { type: '', value: 0, unit: 'yen', target: '' };

  // ===== 1. 再描画関数 =====
  function renderBillingTable(rows) {
    const tbody = container.querySelector('#billing-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="7" style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">該当するデータがありません</td></tr>';
      updateKPIs(0, 0, 0);
      return;
    }

    let totalBase = 0, totalDiscount = 0, totalFinal = 0;

    tbody.innerHTML = rows.map(row => {
      const baseAmount = row.請求金額 || 0;
      const discountRate = row.割引率 || 0;
      const discountAmount = Math.floor(baseAmount * discountRate / 100);
      const finalAmount = baseAmount - discountAmount;
      const qualityScore = row.データ品質スコア || 0;
      const qualityBadge = qualityScore >= 80 ? '✓ 良好' : qualityScore >= 60 ? '△ 注意' : '✗ 要確認';

      totalBase += baseAmount;
      totalDiscount += discountAmount;
      totalFinal += finalAmount;

      return `<tr style="border-bottom: 1px solid rgba(255,255,255,0.08); background: ${row.異常検出フラグ ? 'rgba(255,152,0,0.08)' : 'transparent'};">
        <td style="padding: 8px; color: var(--text);">${row.顧客ID || '-'}</td>
        <td style="padding: 8px; color: var(--text);">${row.サービスID || '-'}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">¥${baseAmount.toLocaleString()}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${discountRate}%</td>
        <td style="padding: 8px; text-align: right; color: #ff6a00; font-weight: 600;">-¥${discountAmount.toLocaleString()}</td>
        <td style="padding: 8px; text-align: right; color: #4caf50; font-weight: 600;">¥${finalAmount.toLocaleString()}</td>
        <td style="padding: 8px; text-align: center; font-size: 10px; color: ${qualityScore >= 80 ? '#4caf50' : qualityScore >= 60 ? '#ff9800' : '#f44336'};">${qualityBadge}</td>
      </tr>`;
    }).join('');

    updateKPIs(totalBase, totalDiscount, totalFinal);
  }

  function updateKPIs(base, discount, final) {
    container.querySelector('#kpi-base-amount').textContent = `¥${base.toLocaleString()}`;
    container.querySelector('#kpi-discount-amount').textContent = `-¥${discount.toLocaleString()}`;
    container.querySelector('#kpi-final-amount').textContent = `¥${final.toLocaleString()}`;
  }

  function updateQualityStatus(rows) {
    const statusDiv = container.querySelector('#quality-status');
    if (!rows || rows.length === 0) {
      statusDiv.innerHTML = '<div>検証状態: <span style="color: var(--text);">未実行</span></div><div>異常件数: <span style="color: var(--text);">0</span></div><div>品質スコア: <span style="color: var(--text);">-</span></div>';
      return;
    }
    const errorCount = rows.filter(r => r.検証ステータス === '不合格').length;
    const avgScore = Math.round(rows.reduce((sum, r) => sum + (r.データ品質スコア || 0), 0) / rows.length);
    statusDiv.innerHTML = `<div>検証状態: <span style="color: var(--text);">検証済み</span></div><div>異常件数: <span style="color: ${errorCount > 0 ? '#f44336' : '#4caf50'};">${errorCount}</span></div><div>品質スコア: <span style="color: var(--text);">${avgScore}点</span></div>`;
  }

  function updateMissingDataAlert(rows) {
    const alertDiv = container.querySelector('#missing-data-alert');
    if (!rows || rows.length === 0) {
      alertDiv.style.display = 'none';
      return;
    }
    const missingItems = rows.slice(0, 5).map(r => `• ${r.不足項目名}`).join('<br>');
    container.querySelector('#missing-data-list').innerHTML = missingItems + (rows.length > 5 ? `<br>他 ${rows.length - 5} 件` : '');
    alertDiv.style.display = 'block';
  }

  // ===== 2. 初期データ読込 =====
  if (tables[billingTableIndex] && tables[billingTableIndex].records) {
    currentBillingData = tables[billingTableIndex].records;
    renderBillingTable(currentBillingData);
  }

  // ===== 3. データ読込ボタン =====
  container.querySelector('#btn-load-data').addEventListener('click', async () => {
    const startMonth = container.querySelector('#period-start').value;
    const endMonth = container.querySelector('#period-end').value;

    if (!startMonth || !endMonth) {
      alert('開始年月と終了年月を選択してください');
      return;
    }

    const rows = await window.aivicApi.list(billingTableIndex);
    if (!rows) return;

    // 期間フィルタリング
    const filtered = rows.filter(r => {
      const month = r.請求年月;
      return month >= startMonth && month <= endMonth;
    });

    currentBillingData = filtered;
    renderBillingTable(currentBillingData);

    // 品質検証データも読込
    const qualityRows = await window.aivicApi.list(qualityTableIndex);
    if (qualityRows) updateQualityStatus(qualityRows);

    // 不足データ警告も読込
    const missingRows = await window.aivicApi.list(missingTableIndex);
    if (missingRows) updateMissingDataAlert(missingRows);
  });

  // ===== 4. 割引適用ボタン =====
  container.querySelector('#btn-apply-discount').addEventListener('click', () => {
    const type = container.querySelector('#discount-type').value;
    const value = parseFloat(container.querySelector('#discount-value').value) || 0;
    const unit = container.querySelector('#discount-unit').value;
    const target = container.querySelector('#discount-target').value;

    if (!type || !target) {
      alert('割引タイプと適用対象を選択してください');
      return;
    }

    appliedDiscount = { type, value, unit, target };

    // 割引率を計算して再描画
    const updated = currentBillingData.map(row => {
      let discountRate = 0;
      if (target === 'all') {
        discountRate = unit === 'percent' ? value : Math.floor((value / (row.請求金額 || 1)) * 100);
      } else if (target === 'customer' && row.顧客ID) {
        // 顧客別割引ロジック（簡略版）
        discountRate = unit === 'percent' ? value : Math.floor((value / (row.請求金額 || 1)) * 100);
      } else if (target === 'service' && row.サービスID) {
        // サービス別割引ロジック（簡略版）
        discountRate = unit === 'percent' ? value : Math.floor((value / (row.請求金額 || 1)) * 100);
      }
      return { ...row, 割引率: Math.min(discountRate, 100) };
    });

    currentBillingData = updated;
    renderBillingTable(currentBillingData);
    alert(`割引を適用しました: ${type} ${value}${unit === 'percent' ? '%' : '円'}`);
  });

  // ===== 5. 品質検証ボタン =====
  container.querySelector('#btn-check-quality').addEventListener('click', async () => {
    const qualityRows = await window.aivicApi.list(qualityTableIndex);
    if (qualityRows) {
      updateQualityStatus(qualityRows);
      alert('品質検証を実行しました');
    }
  });

  // ===== 6. 異常検出ログ確認ボタン =====
  container.querySelector('#btn-view-anomaly').addEventListener('click', () => {
    window.showScreen('scr-1781953477562'); // 営業データ異常検出・確認画面
  });

  // ===== 7. CSVエクスポートボタン =====
  container.querySelector('#btn-export-csv').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(billingTableIndex);
    if (!rows || rows.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['顧客ID', 'サービスID', '請求年月', '基本請求額', '割引率', '割引額', '確定額', '品質スコア'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...rows.map(r => {
        const baseAmount = r.請求金額 || 0;
        const discountRate = r.割引率 || 0;
        const discountAmount = Math.floor(baseAmount * discountRate / 100);
        const finalAmount = baseAmount - discountAmount;
        return [r.顧客ID, r.サービスID, r.請求年月, baseAmount, discountRate, discountAmount, finalAmount, r.データ品質スコア || 0].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `billing_summary_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // ===== 8. 請求額確定ボタン =====
  container.querySelector('#btn-confirm-billing').addEventListener('click', async () => {
    if (currentBillingData.length === 0) {
      alert('確定するデータがありません');
      return;
    }

    const confirmed = confirm(`${currentBillingData.length}件の請求額を確定してよろしいですか？`);
    if (!confirmed) return;

    // 各行を更新（集計ステータスを「確定」に）
    for (const row of currentBillingData) {
      await window.aivicApi.update(billingTableIndex, row.請求集計ID, {
        集計ステータス: '確定',
        請求確定日時: new Date().toISOString()
      });
    }

    alert('請求額を確定しました');
    // 確定後、請求額集計・確認画面へ遷移
    window.showScreen('scr-1781953491946');
  });
}
